import{_ as n,I as r,c as s,o as i,j as a,J as o,a5 as d,a as l}from"./chunks/framework.CUJoMJm2.js";const b=JSON.parse('{"title":"Protocol Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/architecture.md","filePath":"protocols/architecture.md","lastUpdated":0}'),c={name:"protocols/architecture.md"};function p(h,e,u,y,m,g){const t=r("CopyOrDownloadAsMarkdownButtons");return i(),s("div",null,[e[0]||(e[0]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /protocols/architecture.md for this page in Markdown format",-1)),e[1]||(e[1]=a("h1",{id:"protocol-architecture",tabindex:"-1"},[l("Protocol Architecture "),a("a",{class:"header-anchor",href:"#protocol-architecture","aria-label":"Permalink to “Protocol Architecture”"},"​")],-1)),o(t),e[2]||(e[2]=d(`<blockquote><p><strong>Authority</strong>: Primary (Normative)<br><strong>Purpose</strong>: Layer boundaries, frame wrapping rules, and dependency invariants. Final arbiter when layer specs conflict.</p></blockquote><p>This document defines frame wrapping rules, dependency invariants, and layer boundaries. Lower-level details (frame encoding, cryptography, RPC envelopes) are documented in referenced specifications. This document is the final arbiter of layer architecture; conflicts indicate bugs in lower-level specs which MUST be updated to comply.</p><h2 id="document-conventions" tabindex="-1">Document Conventions <a class="header-anchor" href="#document-conventions" aria-label="Permalink to “Document Conventions”">​</a></h2><ul><li><strong>Normative</strong>: Sections using MUST/SHOULD/MAY define required behavior</li><li><strong>Non-normative</strong>: Examples, notes, and diagrams illustrate but do not constrain implementations</li></ul><h2 id="layer-stack" tabindex="-1">Layer Stack <a class="header-anchor" href="#layer-stack" aria-label="Permalink to “Layer Stack”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Application / SDK                                                  │</span></span>
<span class="line"><span>│  (@sideband/peer, @sideband/cli)                                    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  RPC Layer                                                          │</span></span>
<span class="line"><span>│  Typed request/response/notification semantics                      │</span></span>
<span class="line"><span>│  Lives inside: MessageFrame.data                                    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  SBP (Sideband Protocol)                                            │</span></span>
<span class="line"><span>│  Application framing: Control, Message, Ack, Error                  │</span></span>
<span class="line"><span>│  Topology-agnostic, no encryption, no transport                     │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Session Layer                                                      │</span></span>
<span class="line"><span>│  ├─ SBRP (relay mode): E2EE via relay server                        │</span></span>
<span class="line"><span>│  └─ SBDP (direct mode): P2P encryption (future)                     │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Transport                                                          │</span></span>
<span class="line"><span>│  Any ordered transport with integrity (WebSocket, QUIC streams)     │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="data-flow-non-normative" tabindex="-1">Data Flow (Non-normative) <a class="header-anchor" href="#data-flow-non-normative" aria-label="Permalink to “Data Flow (Non-normative)”">​</a></h3><p>When a client sends an RPC request through a relay:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. Application creates RPC request     →  { t: &quot;r&quot;, m: &quot;getUser&quot;, p: {...} }</span></span>
<span class="line"><span>2. RPC encodes to JSON (default) or CBOR →  bytes</span></span>
<span class="line"><span>3. SBP wraps in MessageFrame           →  [header][frameId][subject][data]</span></span>
<span class="line"><span>4. SBRP encrypts complete SBP frame    →  [nonce][ciphertext][authTag]</span></span>
<span class="line"><span>5. SBRP wraps in Data frame (0x03)     →  [type][length][sessionId][encrypted]</span></span>
<span class="line"><span>6. Transport sends over WebSocket      →  binary message</span></span></code></pre></div><p>Encoding is negotiated during handshake via capabilities (default: JSON). The encrypted blob in step 4 contains the full SBP frame bytes (header + frameId + payload).</p><h2 id="frame-wrapping-rules" tabindex="-1">Frame Wrapping Rules <a class="header-anchor" href="#frame-wrapping-rules" aria-label="Permalink to “Frame Wrapping Rules”">​</a></h2><p>These rules are normative. Violations indicate implementation bugs.</p><h3 id="rule-1-sbp-frames-are-application-visible" tabindex="-1">Rule 1: SBP Frames Are Application-Visible <a class="header-anchor" href="#rule-1-sbp-frames-are-application-visible" aria-label="Permalink to “Rule 1: SBP Frames Are Application-Visible”">​</a></h3><p>SBP frames (<code>ControlFrame</code>, <code>MessageFrame</code>, <code>AckFrame</code>, <code>ErrorFrame</code>) are the only frames that application code interacts with. Session layers and transports are invisible to applications.</p><h3 id="rule-2-session-layers-treat-sbp-frames-as-opaque-payloads" tabindex="-1">Rule 2: Session Layers Treat SBP Frames as Opaque Payloads <a class="header-anchor" href="#rule-2-session-layers-treat-sbp-frames-as-opaque-payloads" aria-label="Permalink to “Rule 2: Session Layers Treat SBP Frames as Opaque Payloads”">​</a></h3><p>SBRP and SBDP MUST treat the entire SBP frame (including header, frameId, and payload) as an opaque byte sequence. Session layers:</p><ul><li>MUST NOT parse SBP frame structure</li><li>MUST NOT inspect MessageFrame subjects or data</li><li>MUST NOT depend on SBP semantics for routing decisions</li><li>MUST NOT rewrite any SBP frame field (including frameId)</li></ul><p><strong>SBRP Data frames (type 0x03) carry encrypted SBP frames.</strong> This includes SBP <code>ControlFrame</code> (handshake, ping, pong), <code>MessageFrame</code> (application data), <code>AckFrame</code>, and <code>ErrorFrame</code>. After decryption, endpoints deserialize the plaintext using <code>@sideband/protocol</code> codecs. SBRP never inspects encrypted payload contents.</p><p><strong>Forwarding invariant</strong>: SBRP relays forward encrypted SBP frames without modification; they never terminate SBP links. If a separate component (an SBP proxy) terminates an SBP link and re-originates frames on a new link, it MUST generate new frameIds on the outbound link—this creates two back-to-back SBP sessions, not frame forwarding.</p><h3 id="rule-3-rpc-envelopes-are-invisible-to-all-lower-layers" tabindex="-1">Rule 3: RPC Envelopes Are Invisible to All Lower Layers <a class="header-anchor" href="#rule-3-rpc-envelopes-are-invisible-to-all-lower-layers" aria-label="Permalink to “Rule 3: RPC Envelopes Are Invisible to All Lower Layers”">​</a></h3><p>RPC envelopes exist only inside <code>MessageFrame.data</code>. They are:</p><ul><li>Invisible to SBP framing (SBP routes by <code>subject</code> but does not interpret <code>data</code> contents)</li><li>Invisible to session layers (which see encrypted SBP frames)</li><li>Invisible to transports (which see binary messages)</li></ul><h3 id="rule-4-frame-identity-is-layer-scoped" tabindex="-1">Rule 4: Frame Identity Is Layer-Scoped <a class="header-anchor" href="#rule-4-frame-identity-is-layer-scoped" aria-label="Permalink to “Rule 4: Frame Identity Is Layer-Scoped”">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Identity Field</th><th>Wire Key</th><th>Scope</th><th>Reused Across Layers?</th></tr></thead><tbody><tr><td>SBP</td><td><code>frameId</code></td><td><code>id</code></td><td>Sender-local unique</td><td>No</td></tr><tr><td>SBRP</td><td><code>SessionID</code></td><td>(header)</td><td>Relay routing multiplexer</td><td>No</td></tr><tr><td>RPC</td><td><code>cid</code></td><td><code>cid</code></td><td>End-to-end correlation</td><td>No</td></tr></tbody></table><p><strong>frameId</strong>: Identifies frames at their origin; never rewritten by SBRP relays (see Rule 2). Used for Ack linkage within a single SBP link. Receivers MUST NOT reuse a received frameId in outbound frames. AckFrame generation MAY be performed by the runtime on behalf of the application.</p><p><strong>cid</strong>: RPC correlation ID copied from request to response. Preserved end-to-end through relays. Enables multi-hop routing while keeping SBP topology-agnostic.</p><p><strong>SessionID</strong>: SBRP-specific uint64 in frame headers for relay multiplexing. Distinct from JWT <code>sid</code> claim used for authentication (see Session terminology below).</p><p>See ADR-010 for detailed rationale on frameId vs cid separation.</p><h2 id="dependency-invariants" tabindex="-1">Dependency Invariants <a class="header-anchor" href="#dependency-invariants" aria-label="Permalink to “Dependency Invariants”">​</a></h2><p>These invariants MUST be preserved. Violations require an ADR to justify.</p><h3 id="sbp-dependencies" tabindex="-1">SBP Dependencies <a class="header-anchor" href="#sbp-dependencies" aria-label="Permalink to “SBP Dependencies”">​</a></h3><p>SBP MUST NOT depend on:</p><ul><li>Session layer semantics (SBRP, SBDP)</li><li>Transport guarantees (ordering, delivery)</li><li>RPC envelope structure</li></ul><p>SBP MAY be used directly over any byte-stream transport without a session layer (e.g., loopback testing, trusted networks).</p><h3 id="rpc-dependencies" tabindex="-1">RPC Dependencies <a class="header-anchor" href="#rpc-dependencies" aria-label="Permalink to “RPC Dependencies”">​</a></h3><p>RPC MUST NOT depend on:</p><ul><li>Session layer semantics</li><li>Transport guarantees</li><li>Encryption status (RPC works identically encrypted or plaintext)</li></ul><p>RPC depends only on SBP <code>MessageFrame</code> for framing.</p><h3 id="session-layer-dependencies" tabindex="-1">Session Layer Dependencies <a class="header-anchor" href="#session-layer-dependencies" aria-label="Permalink to “Session Layer Dependencies”">​</a></h3><p>SBRP and SBDP:</p><ul><li>MUST NOT inspect SBP payload contents</li><li>MUST NOT depend on RPC semantics</li><li>MUST NOT initiate SBP frames (application or runtime generates all SBP frames)</li><li>MUST treat received SBP frames as opaque and forward unchanged</li><li>MAY have their own control messages (e.g., SBRP <code>RelayNotification</code> frames) that are session-layer scoped, not SBP-scoped</li></ul><h3 id="transport-dependencies" tabindex="-1">Transport Dependencies <a class="header-anchor" href="#transport-dependencies" aria-label="Permalink to “Transport Dependencies”">​</a></h3><p>Transports (<code>@sideband/transport-*</code>):</p><ul><li>MUST NOT assume SBP semantics</li><li>MUST NOT parse any layer above raw bytes</li><li>MUST NOT generate frames for any layer</li></ul><h2 id="terminology-disambiguation" tabindex="-1">Terminology Disambiguation <a class="header-anchor" href="#terminology-disambiguation" aria-label="Permalink to “Terminology Disambiguation”">​</a></h2><h3 id="control-at-different-layers" tabindex="-1">&quot;Control&quot; at Different Layers <a class="header-anchor" href="#control-at-different-layers" aria-label="Permalink to “&quot;Control&quot; at Different Layers”">​</a></h3><p>Two distinct constructs use &quot;Control&quot; terminology:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Construct</th><th>Wire Type</th><th>Encrypted?</th><th>Purpose</th></tr></thead><tbody><tr><td>SBP</td><td><code>ControlFrame</code></td><td>kind=0</td><td>Yes (E2EE)</td><td>Handshake, Ping, Pong, Close</td></tr><tr><td>SBRP</td><td><code>RelayNotification</code></td><td>0x20</td><td>Never</td><td>Relay-to-endpoint notifications</td></tr></tbody></table><p>These are unrelated:</p><ul><li><strong>SBP ControlFrame</strong>: Application-level protocol control (peer handshake, keepalive). Travels end-to-end inside SBRP Data frames, encrypted.</li><li><strong>SBRP RelayNotification</strong>: Relay-generated notifications (<code>session_paused</code>, <code>rate_limited</code>). Sent plaintext from relay to endpoint only. (Wire type 0x20; historically called &quot;Control frame&quot; but renamed to avoid confusion with SBP ControlFrame.)</li></ul><h3 id="session-at-different-layers" tabindex="-1">&quot;Session&quot; at Different Layers <a class="header-anchor" href="#session-at-different-layers" aria-label="Permalink to “&quot;Session&quot; at Different Layers”">​</a></h3><p>The unqualified term &quot;session&quot; is ambiguous and SHOULD NOT be used in specifications or code. Use these qualified terms:</p><table tabindex="0"><thead><tr><th>Context</th><th>Qualified Term</th><th>Type / Encoding</th><th>Meaning</th></tr></thead><tbody><tr><td>SBRP wire format</td><td><code>SessionID</code></td><td>uint64 (big-endian)</td><td>Relay routing multiplexer; wire layer only</td></tr><tr><td>SBRP authentication</td><td><code>SessionToken</code></td><td>JWT with <code>sid</code> claim</td><td>Auth binding; relay validates against SessionID</td></tr><tr><td>SBRP cryptography</td><td><code>SessionState</code></td><td>Binary (keys, counters)</td><td>E2EE encryption per client; endpoint-only</td></tr><tr><td>SBP</td><td>(none)</td><td>—</td><td>SBP has no session concept</td></tr></tbody></table><p>The JWT <code>sid</code> claim is the base64url-encoded 8-byte representation of SessionID uint64, enabling relays to validate that client frames&#39; SessionID field matches the token.</p><h3 id="handshake-at-different-layers" tabindex="-1">&quot;Handshake&quot; at Different Layers <a class="header-anchor" href="#handshake-at-different-layers" aria-label="Permalink to “&quot;Handshake&quot; at Different Layers”">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Construct</th><th>Wire Type</th><th>Encrypted?</th><th>Purpose</th></tr></thead><tbody><tr><td>SBP</td><td>ControlFrame (op=Handshake)</td><td>kind=0, op=0</td><td>Yes (E2EE)</td><td>Peer introduction (peerId, capabilities)</td></tr><tr><td>SBRP</td><td>HandshakeInit/Accept</td><td>0x01, 0x02</td><td>Never</td><td>E2EE key exchange (X25519/Ed25519)</td></tr></tbody></table><p>These are unrelated:</p><ul><li><strong>SBP Handshake</strong>: Application-level peer introduction. Sent encrypted end-to-end within SBRP Data frames once a secure SBP-carrying channel is established.</li><li><strong>SBRP Handshake</strong>: Cryptographic key exchange. Sent plaintext during E2EE channel establishment. Relay forwards without inspection.</li></ul><h3 id="ping-pong-at-different-layers" tabindex="-1">&quot;Ping/Pong&quot; at Different Layers <a class="header-anchor" href="#ping-pong-at-different-layers" aria-label="Permalink to “&quot;Ping/Pong&quot; at Different Layers”">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Construct</th><th>Encrypted?</th><th>Purpose</th><th>Forwarded?</th></tr></thead><tbody><tr><td>SBP</td><td><code>ControlOp.Ping</code></td><td>Yes (E2EE)</td><td>Application-level keepalive</td><td>Yes</td></tr><tr><td>SBRP</td><td><code>Ping</code> (0x10)</td><td>Never</td><td>Connection-level liveness detection</td><td>Never</td></tr></tbody></table><p>SBP Ping/Pong are routable like Messages and encrypted by session layers for end-to-end liveness detection. SBRP Ping/Pong are unencrypted and connection-scoped.</p><h2 id="v1-invariants" tabindex="-1">v1 Invariants <a class="header-anchor" href="#v1-invariants" aria-label="Permalink to “v1 Invariants”">​</a></h2><p>Properties guaranteed in v1 that implementations may rely on:</p><ol><li><strong>frameId is always present</strong>: Every SBP frame has a 16-byte frameId, auto-generated at construction.</li><li><strong>Session layers are opaque</strong>: Applications never see SBRP/SBDP framing.</li><li><strong>Relay is a frame router</strong>: SBRP relay inspects SBRP frame headers (type, length, SessionID) for routing. It never parses encrypted payloads, SBP frames, or RPC envelopes.</li><li><strong>Best-effort delivery</strong>: SBP allows senders to request Ack frames, but neither sending nor acknowledging is mandatory. Reconnection may cause retries at higher layers. Applications requiring reliable delivery must implement idempotency via RPC correlation.</li><li><strong>No guaranteed ordering</strong>: Message ordering depends on transport. Relays and networks may reorder. Applications requiring strict ordering must add sequence numbers.</li></ol><h2 id="non-goals-explicit-deferrals" tabindex="-1">Non-Goals (Explicit Deferrals) <a class="header-anchor" href="#non-goals-explicit-deferrals" aria-label="Permalink to “Non-Goals (Explicit Deferrals)”">​</a></h2><p>These are intentionally not addressed in v1:</p><ol><li><strong>Client cryptographic identity</strong>: Clients use ephemeral keys; no persistent client signing keys.</li><li><strong>Streaming RPC</strong>: <code>stream/</code> subject prefix is reserved but unspecified.</li><li><strong>Multi-hop relay chains</strong>: Single relay only.</li><li><strong>Cross-session message correlation</strong>: Each session is independent.</li><li><strong>SBDP implementation</strong>: Design principles documented; full spec deferred.</li></ol><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to “Related Documents”">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Authority</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./sbp/">SBP Specification</a></td><td>Normative (SBP layer)</td><td>Frame encoding, wire format, routing</td></tr><tr><td><a href="./sbrp/">SBRP Specification</a></td><td>Normative (SBRP layer)</td><td>Session crypto, relay responsibilities</td></tr><tr><td><a href="./sbdp/">SBDP Specification</a></td><td>Design only (future)</td><td>P2P session layer principles</td></tr><tr><td><a href="./rpc/">RPC Specification</a></td><td>Normative (RPC layer)</td><td>Envelope format, correlation</td></tr><tr><td><a href="./../adr/002-naming-matrix">ADR-002: Naming Matrix</a></td><td>Canonical</td><td>Type/field names across all layers</td></tr><tr><td><a href="./../adr/010-rpc-correlation-cid">ADR-010: RPC Correlation</a></td><td>Canonical</td><td>frameId vs cid semantics</td></tr></tbody></table><p><strong>Authority hierarchy</strong>: This document defines intended layering and dependencies. Conflicts indicate bugs; lower-level specs MUST be updated to comply. This document is updated only if the architecture itself changes.</p>`,70))])}const P=n(c,[["render",p]]);export{b as __pageData,P as default};
